"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[259],{95562:e=>{e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"defaultSidebar":[{"type":"link","label":"What is Squish?","href":"/Squish/docs/intro","docId":"intro","unlisted":false},{"type":"link","label":"Differences from Squash?","href":"/Squish/docs/differences","docId":"differences","unlisted":false},{"type":"link","label":"How To Serialize?","href":"/Squish/docs/how","docId":"how","unlisted":false},{"type":"link","label":"Advanced Techniques","href":"/Squish/docs/custom","docId":"custom","unlisted":false},{"type":"category","label":"Remote Events","collapsible":true,"collapsed":false,"items":[{"type":"link","label":"Packet Format And Insights","href":"/Squish/docs/RemoteEvents/binary","docId":"RemoteEvents/binary","unlisted":false},{"type":"link","label":"Benchmarks and Measurements","href":"/Squish/docs/RemoteEvents/benchmarks","docId":"RemoteEvents/benchmarks","unlisted":false}]}]},"docs":{"custom":{"id":"custom","title":"Advanced Techniques","description":"Custom Serializers","sidebar":"defaultSidebar"},"differences":{"id":"differences","title":"Differences from Squash?","description":"This is largely similar to the Squash (it is a fork, after all). Only the important differences will be listed below.","sidebar":"defaultSidebar"},"how":{"id":"how","title":"How To Serialize?","description":"Every byte can represent 256 possible values. We can represent 256^2 = 65536 possible values with 2 bytes, 256^3 = 16777216 possible values with 3 bytes, and so on. There are many ways to interpret these bytes depending on context which is the key to serialization. All serialization does is turn information into data, in this case datatype instances to buffers. If used smartly, less data can be used to represent the same information which is what Squish exploits as much as possible.","sidebar":"defaultSidebar"},"intro":{"id":"intro","title":"What is Squish?","description":"This is a fork of Squash, with many differences and performance optimizations.","sidebar":"defaultSidebar"},"RemoteEvents/benchmarks":{"id":"RemoteEvents/benchmarks","title":"Benchmarks and Measurements","description":"Eyeballed Lookup Table","sidebar":"defaultSidebar"},"RemoteEvents/binary":{"id":"RemoteEvents/binary","title":"Packet Format And Insights","description":"Buffers are great for serializing data, but we need to know when to serialize. Certain kinds of data is cheaper to send over the network than others. This page is very technical, as it introduces the raw binary format remotes use internally and discusses the overhead of each type of data. If you are looking for how to use Squish go to How To Serialize?.","sidebar":"defaultSidebar"}}}}')}}]);